  `vm` varchar(30) NOT NULL,
  `ip_servidor` varchar(20) NOT NULL,
  `ticket_incl` int(11) NOT NULL,
  `data_incl` date NOT NULL,
  `case_` int(11) NOT NULL,
  `data_canc` date DEFAULT NULL,
  `ticket_canc` int(11) DEFAULT NULL,
  `obs` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `port_servidor_UNIQUE` (`port_servidor`)
) ENGINE=InnoDB AUTO_INCREMENT=1851 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_520_ci;
